import{_ as l,r as t,o as d,c,b as n,a as r,w as i,d as o,e as a}from"./chunks/framework.BAcwvmoc.js";const u="/assets/despliegue.BmYKZjj5.png",p="/assets/analisis_netcraft.DyjkwQhj.png",g="/assets/servidor_aplicaciones.CuKGe-sv.png",P=JSON.parse('{"title":"WWW","description":"","frontmatter":{"title":"WWW"},"headers":[],"relativePath":"fundamentos-web/web/index.md","filePath":"02_fundamentos_web/05_www/index.md"}'),m={name:"fundamentos-web/web/index.md"};function v(b,e,f,S,w,y){const s=t("Color");return d(),c("div",null,[e[11]||(e[11]=n('<div class="daws-objetivos daws-container"><div class="daws-objetivos__header"><i class="fa-solid fa-list-check" aria-hidden="true"></i><span>Objetivos</span></div><div class="daws-objetivos__content"><div class="daws-objetivos__title">Historia y arquitectura de la web</div><div class="daws-objetivos__body"><ul><li>Realizar instalaciones</li></ul></div></div></div><h2 id="breve-historia-de-la-www" tabindex="-1">Breve Historia de la WWW <a class="header-anchor" href="#breve-historia-de-la-www" aria-label="Permalink to &quot;Breve Historia de la WWW&quot;">​</a></h2>',2)),r(s,null,{default:i(()=>[...e[0]||(e[0]=[o("La WWW en la red World Wide Web",-1)])]),_:1}),r(s,null,{default:i(()=>[...e[1]||(e[1]=[o("Varios períodos en la historia de la web",-1)])]),_:1}),e[12]||(e[12]=n("<ul><li><p><strong>1980 – 1990</strong>: desarrollo del concepto de la web. Tim Berners-Lee introduce la idea de un sistema de información global basado en hipertexto.</p></li><li><p><strong>1992 – 1995</strong>: expansión del uso de Internet. Creación de los primeros navegadores gráficos (como Mosaic) que permiten a los usuarios comunes interactuar con la web.</p></li><li><p><strong>1996 – 1998</strong>: primeras etapas de comercio en la web. Comienza a surgir el comercio electrónico con empresas pioneras como Amazon y eBay.</p></li><li><p><strong>1999 – 2001</strong>: la burbuja de las empresas .com. El auge y colapso de muchas startups relacionadas con Internet que no tenían un modelo de negocio sostenible.</p></li><li><p><strong>2002 – 2006: La expansión de la Web 2.0</strong>:</p><ul><li><strong>Web 2.0</strong>: este período marca el auge de la llamada Web 2.0, donde los usuarios pasan de ser meros consumidores de información a ser creadores de contenido. Plataformas como <strong>MySpace</strong> (2003), <strong>Facebook</strong> (2004) y <strong>YouTube</strong> (2005) introducen nuevas formas de interacción, centradas en la participación activa.</li><li><strong>Tecnologías clave</strong>: durante esta época se popularizan tecnologías como <strong>AJAX</strong>, que permite a los desarrolladores web crear aplicaciones más rápidas y dinámicas, mejorando la experiencia de usuario.</li><li><strong>Primeros pasos del comercio en la nube</strong>: aunque aún en su fase inicial, empresas como <strong>Amazon</strong> comienzan a ofrecer servicios en la nube, sentando las bases de lo que será la computación en la nube.</li></ul></li><li><p><strong>2007 – 2012: La revolución móvil y la nube</strong>:</p><ul><li><strong>El iPhone y el auge de los smartphones</strong>: en 2007, el lanzamiento del <strong>iPhone</strong> revoluciona el acceso a la web. Los usuarios comienzan a conectarse a Internet desde dispositivos móviles a gran escala, y esto impulsa el diseño web responsivo.</li><li><strong>La explosión de las aplicaciones móviles</strong>: a medida que los smartphones se convierten en una parte fundamental de la vida diaria, las aplicaciones móviles comienzan a competir con las páginas web en importancia. Servicios como <strong>App Store</strong> (2008) y <strong>Google Play</strong> (2008) permiten a los desarrolladores ofrecer aplicaciones directamente a los usuarios.</li><li><strong>Servicios en la nube</strong>: en esta etapa, la computación en la nube empieza a consolidarse con la expansión de plataformas como <strong>Amazon Web Services (AWS)</strong> (2006), que ofrece infraestructura escalable para aplicaciones web.</li></ul></li><li><p><strong>2013 – 2017: La era del Big Data y la privacidad</strong>:</p><ul><li><strong>Big Data</strong>: el crecimiento de los servicios en línea genera enormes cantidades de datos, lo que lleva al auge de tecnologías de análisis masivo de datos o <strong>Big Data</strong>. Empresas como Google y Facebook comienzan a aprovechar estos datos para personalizar la experiencia web, aunque esto suscita debates sobre la privacidad de los usuarios.</li><li><strong>Auge de las redes sociales</strong>: redes sociales como <strong>Instagram</strong> (2010), <strong>WhatsApp</strong> (2010) y <strong>Snapchat</strong> (2011) dominan el panorama digital, cambiando la forma en que los usuarios interactúan entre sí y con la web.</li><li><strong>Ciberseguridad y privacidad</strong>: los crecientes ataques cibernéticos y la recopilación masiva de datos provocan que la seguridad se convierta en una prioridad. Esto lleva a la adopción del protocolo <strong>HTTPS</strong> en la mayoría de los sitios web y al desarrollo de regulaciones de protección de datos como el <strong>GDPR</strong> en Europa.</li></ul></li><li><p><strong>2018 – Actualidad: Inteligencia artificial y descentralización</strong>:</p><ul><li><strong>Inteligencia artificial y machine learning</strong>: tecnologías de IA y <strong>machine learning</strong> comienzan a integrarse en la web para mejorar desde los motores de búsqueda hasta las recomendaciones en plataformas de streaming y redes sociales.</li><li><strong>Blockchain y Web 3.0</strong>: empiezan a surgir conceptos de una <strong>Web 3.0</strong> basada en tecnologías descentralizadas como el <strong>blockchain</strong>, con el objetivo de dar más control a los usuarios sobre sus datos y las transacciones en línea.</li><li><strong>El auge de IoT</strong>: la <strong>Internet de las cosas (IoT)</strong> continúa su expansión, conectando millones de dispositivos al entorno web y transformando sectores como el hogar inteligente, la industria y la salud.</li><li><strong>Impacto de la pandemia (COVID-19)</strong>: la pandemia global de 2020 acelera la digitalización de muchos sectores, aumentando la demanda de aplicaciones web, comercio electrónico y servicios en línea.</li></ul></li></ul>",1)),r(s,null,{default:i(()=>[...e[2]||(e[2]=[o("Perspectivas de presente y futuro",-1)])]),_:1}),e[13]||(e[13]=a("ul",null,[a("li",null,[a("p",null,[a("strong",null,"Auge de las tecnologías móviles"),o(": la web se adapta a los dispositivos móviles, como teléfonos inteligentes y tabletas, que ahora dominan el acceso a Internet.")])]),a("li",null,[a("p",null,[a("strong",null,"Internet de las Cosas (IoT)"),o(": la integración de la web con dispositivos cotidianos, conectándolos a Internet para mejorar la automatización y la comunicación entre dispositivos.")])])],-1)),e[14]||(e[14]=a("h2",{id:"arquitectura",tabindex:"-1"},[o("Arquitectura "),a("a",{class:"header-anchor",href:"#arquitectura","aria-label":'Permalink to "Arquitectura"'},"​")],-1)),e[15]||(e[15]=a("p",null,"Puedes ampliar la idea de la siguiente manera:",-1)),r(s,null,{default:i(()=>[...e[3]||(e[3]=[o("La arquitectura de la WWW es un tanto compleja",-1)])]),_:1}),e[16]||(e[16]=o(" y, sobre todo, ",-1)),r(s,null,{default:i(()=>[...e[4]||(e[4]=[o("muy vasta",-1)])]),_:1}),e[17]||(e[17]=o(".",-1)),e[18]||(e[18]=a("p",null,"Abarca una gran cantidad de elementos interconectados, desde el hardware que sustenta los servidores hasta los diversos protocolos y tecnologías que permiten la comunicación fluida entre los navegadores y los servidores.",-1)),e[19]||(e[19]=a("p",null,"Esta arquitectura incluye múltiples capas, como la física, la de red, la de transporte, y finalmente la aplicación, donde operan los servicios web que utilizamos a diario.",-1)),e[20]||(e[20]=a("p",null,"Sin embargo, pese a su complejidad, podemos simplificar la explicación para comprender mejor su funcionamiento básico.",-1)),e[21]||(e[21]=a("p",null,"Para centrarnos, vamos a exponer el proceso que ocurre en una solicitud de una página web que podemos ver en la siguiente imagen:",-1)),e[22]||(e[22]=a("p",null,[a("img",{src:u,alt:"Esquema de solicitud de una página web"})],-1)),r(s,null,{default:i(()=>[...e[5]||(e[5]=[o("Esquema del proceso de solicitud de una página web",-1)])]),_:1}),e[23]||(e[23]=n('<ol><li><strong>Navegador del cliente</strong>:</li></ol><ul><li>El usuario introduce una URL en el navegador web (ejemplo: <code>www.ejemplo.com</code>).</li></ul><ol start="2"><li><strong>Consulta DNS</strong>:</li></ol><ul><li>El navegador envía una solicitud al <strong>servidor DNS</strong> para obtener la dirección IP correspondiente al nombre de dominio.</li></ul><ol start="3"><li><strong>Petición HTTP/HTTPS</strong>:</li></ol><ul><li>El navegador realiza una solicitud <strong>HTTP/HTTPS</strong> a la dirección IP obtenida, pidiendo el recurso (una página web, archivo, etc.).</li></ul><ol start="4"><li><strong>Servidor Web</strong>:</li></ol><ul><li>El <strong>servidor web</strong> (como Apache o Nginx) recibe la solicitud y verifica el recurso solicitado.</li></ul><ol start="5"><li><strong>Servidor de Aplicaciones</strong> (si aplica):</li></ol><ul><li>Si la página requiere procesamiento dinámico (PHP, Java, Python, etc.), el <strong>servidor de aplicaciones</strong> genera el contenido necesario.</li></ul><ol start="6"><li><strong>Servidor de Bases de Datos</strong> (si aplica):</li></ol><ul><li>Si es necesario, el servidor de aplicaciones consulta el <strong>servidor de bases de datos</strong> para obtener datos (ejemplo: contenido de un blog, productos de una tienda).</li></ul><ol start="7"><li><strong>Respuesta del Servidor</strong>:</li></ol><ul><li>El servidor web envía el contenido solicitado de vuelta al navegador, ya sea una página estática o dinámica.</li></ul><ol start="8"><li><strong>Renderizado en el Navegador</strong>:</li></ol><ul><li>El navegador interpreta el HTML, CSS y JavaScript recibidos, y muestra la página al usuario.</li></ul><div class="warning custom-block"><p class="custom-block-title">Nota</p><ul><li><strong>Caché</strong>: dependiendo de la configuración, el navegador o un servicio intermedio (CDN, caché del servidor) puede almacenar una copia temporal del recurso para acelerar solicitudes futuras.</li></ul></div><h3 id="servidores-web" tabindex="-1">Servidores web <a class="header-anchor" href="#servidores-web" aria-label="Permalink to &quot;Servidores web&quot;">​</a></h3><p><a href="https://www.netcraft.com/blog/january-2024-web-server-survey/" target="_blank" rel="noreferrer">En esta página de Netcraft</a> podemos ver un análisis mensual de la cuota de mercado de servidores web, basado en el número de sitios web, dominios y computadoras activas.</p>',19)),a("p",null,[e[8]||(e[8]=o("Como podemos ver en la imagen, ",-1)),r(s,null,{default:i(()=>[...e[6]||(e[6]=[o("en enero de 2024",-1)])]),_:1}),e[9]||(e[9]=o(", el estudio reporta cambios en la popularidad de servidores como ",-1)),r(s,null,{default:i(()=>[...e[7]||(e[7]=[o("nginx (23.21% de los sitios web) y Apache (20.70%)",-1)])]),_:1}),e[10]||(e[10]=o(". También incluye información sobre el crecimiento de Cloudflare y OpenResty, así como actualizaciones sobre software relevante para servidores.",-1))]),e[24]||(e[24]=n('<p><img src="'+p+'" alt="Análisis Netcraft"></p><h4 id="servidor-web-algunas-caracteristicas" tabindex="-1">Servidor web: algunas características <a class="header-anchor" href="#servidor-web-algunas-caracteristicas" aria-label="Permalink to &quot;Servidor web: algunas características&quot;">​</a></h4><ul><li><strong>Contenido estático y dinámico</strong>: soporte para contenido estático (HTML) y dinámico (mediante CGI, intérpretes de PHP, Python, etc.).</li><li><strong>Host virtuales</strong>: permite manejar varias direcciones web desde una única dirección IP.</li><li><strong>Velocidad de respuesta</strong>: autorregulación de la velocidad de respuesta según la demanda.</li><li><strong>Autenticación básica</strong>: integración con sistemas de autenticación para acceso restringido.</li><li><strong>Soporte de SSL</strong>: capacidad de cifrar la comunicación mediante HTTPS.</li><li><strong>Módulos</strong>: extensible mediante módulos para soporte de nuevas características.</li></ul><hr><h3 id="servidor-de-aplicaciones" tabindex="-1">Servidor de aplicaciones <a class="header-anchor" href="#servidor-de-aplicaciones" aria-label="Permalink to &quot;Servidor de aplicaciones&quot;">​</a></h3><ul><li><p>Un servidor de aplicaciones es un paquete de software que proporciona servicios a las aplicaciones, como:</p><ul><li><strong>Seguridad</strong></li><li><strong>Balanceo de carga</strong></li><li><strong>Gestión de sistemas distribuidos</strong></li></ul></li><li><p>Inicialmente, estos servidores aparecieron en la plataforma <strong>Java</strong>, pero hoy en día se usan para todo tipo de tecnologías.</p></li><li><p>Los servidores web y de aplicaciones suelen trabajar juntos, aunque son diferentes. Un servidor de aplicaciones necesita de un servidor web para funcionar.</p></li></ul><p><img src="'+g+'" alt="Servidor de aplicaciones"></p><hr><h3 id="servidor-de-bases-de-datos" tabindex="-1">Servidor de bases de datos <a class="header-anchor" href="#servidor-de-bases-de-datos" aria-label="Permalink to &quot;Servidor de bases de datos&quot;">​</a></h3><ul><li><strong>Tipos de bases de datos</strong>: <ul><li><strong>Relacionales</strong>: MySQL, Oracle, SQL Server, MariaDB</li><li><strong>No relacionales</strong>: MongoDB</li></ul></li></ul><hr><h3 id="servidores-complementarios" tabindex="-1">Servidores complementarios <a class="header-anchor" href="#servidores-complementarios" aria-label="Permalink to &quot;Servidores complementarios&quot;">​</a></h3><ul><li><p><strong>Correo</strong>:</p><ul><li>Servidores como <strong>Postfix</strong> o <strong>Sendmail</strong>.</li><li>Extensiones como <strong>SPF</strong> para verificación y control de SPAM.</li><li>Generalmente se delega al proveedor del servicio.</li></ul></li><li><p><strong>DNS</strong>:</p><ul><li>Servidores como <strong>Bind</strong> gestionan la resolución de nombres en Internet.</li><li>También puede ser gestionado por el proveedor.</li></ul></li></ul><hr><h3 id="servidores-complementarios-proxies" tabindex="-1">Servidores complementarios: proxies <a class="header-anchor" href="#servidores-complementarios-proxies" aria-label="Permalink to &quot;Servidores complementarios: proxies&quot;">​</a></h3><ul><li><p>Un <strong>proxy</strong> actúa como intermediario entre el cliente y el servidor web.</p><ul><li><p><strong>Proxy directo</strong>:</p><ul><li>Mejora la eficiencia y seguridad al controlar el acceso a redes externas.</li><li>Ofrece funcionalidades de caché y autenticación.</li></ul></li><li><p><strong>Proxy inverso</strong>:</p><ul><li>Se coloca entre el cliente y los servidores internos.</li><li>Permite balancear la carga entre varios servidores.</li><li>Mejora el rendimiento al ofrecer caché.</li><li>Un proxy inverso puede servir múltiples servidores desde la misma URI.</li></ul></li></ul></li></ul><hr><h3 id="infraestructura-hardware" tabindex="-1">Infraestructura hardware <a class="header-anchor" href="#infraestructura-hardware" aria-label="Permalink to &quot;Infraestructura hardware&quot;">​</a></h3><ul><li><strong>Cloud Computing</strong>: <ul><li><p>Se basa en la provisión de servicios informáticos a través de la nube, sin depender de dispositivos específicos.</p></li><li><p>Ventajas:</p><ul><li><strong>Agilidad</strong>: mejores recursos para el usuario.</li><li><strong>Coste</strong>: reducidos en comparación con infraestructura física.</li><li><strong>Escalabilidad</strong>: ajuste de recursos según demanda.</li><li><strong>Rendimiento mejorado</strong>.</li></ul></li><li><p>Desventajas:</p><ul><li>Dependencia de la conexión a Internet.</li><li>Los datos sensibles pueden no estar completamente bajo el control de la empresa.</li><li>Curvas de aprendizaje elevadas debido a cambios continuos en la tecnología.</li></ul></li></ul></li></ul><hr><h3 id="modelos-de-servicios-cloud" tabindex="-1">Modelos de servicios cloud <a class="header-anchor" href="#modelos-de-servicios-cloud" aria-label="Permalink to &quot;Modelos de servicios cloud&quot;">​</a></h3><ul><li><p><strong>IaaS (Infrastructure as a Service)</strong>:</p><ul><li>Provisión de recursos físicos y virtuales, como máquinas virtuales, almacenamiento, y balanceadores de carga.</li><li>Se usan hipervisores como <strong>Xen</strong>, <strong>KVM</strong>, <strong>VMware ESX/ESXi</strong> o <strong>Hyper-V</strong>.</li><li>Ejemplos: <strong>Amazon EC2</strong>, <strong>Azure VM</strong>, <strong>OpenStack</strong>.</li></ul></li><li><p><strong>PaaS (Platform as a Service)</strong>:</p><ul><li>Permite desarrollar, ejecutar y gestionar aplicaciones sin preocuparse por la infraestructura.</li><li>Se puede ejecutar sobre IaaS, máquinas físicas o contenedores.</li><li>Ejemplos: <strong>Google App Engine</strong>, <strong>OpenShift</strong>, <strong>Heroku</strong>.</li></ul></li><li><p><strong>SaaS (Software as a Service)</strong>:</p><ul><li>Aplicaciones disponibles a través de Internet.</li><li>Ejemplos: <strong>Google Docs</strong>, <strong>Dropbox</strong>, <strong>Twitter</strong>, <strong>Netflix</strong>.</li></ul></li><li><p><strong>CaaS (Container as a Service)</strong>:</p><ul><li><p>Nuevo concepto entre IaaS y PaaS, basado en el uso de contenedores.</p></li><li><p>Permite desplegar aplicaciones sin necesidad de virtualización completa.</p></li><li><p>Ejemplos: <strong>Docker</strong>, <strong>OpenStack Magnum</strong>, <strong>Kubernetes</strong>, <strong>Rancher</strong>:</p><ul><li><p><strong>Docker</strong>: es una plataforma de contenedores que permite empaquetar aplicaciones y todas sus dependencias en contenedores ligeros. Facilita la portabilidad entre entornos y el despliegue rápido de aplicaciones, tanto en desarrollo como en producción.</p></li><li><p><strong>Kubernetes</strong>: es una plataforma de orquestación de contenedores que automatiza el despliegue, escalado y operación de aplicaciones en contenedores. Facilita la gestión de múltiples contenedores en clústeres, distribuyendo la carga y asegurando alta disponibilidad.</p></li><li><p><strong>OpenStack Magnum</strong>: es una solución de OpenStack para gestionar contenedores mediante orquestadores como Kubernetes o Docker Swarm, integrándose en infraestructuras OpenStack.</p></li><li><p><strong>Rancher</strong>: es una plataforma que simplifica la gestión de Kubernetes y contenedores, ofreciendo una interfaz intuitiva para gestionar clústeres Kubernetes en múltiples entornos (nubes, servidores físicos).</p></li></ul></li></ul></li></ul>',22))])}const h=l(m,[["render",v]]);export{P as __pageData,h as default};
